13	impl FormatRule<MdInlineItemList> for FormatMdInlineItemList {
14	    type Context = MarkdownFormatContext;
15	    fn fmt(&self, node: &MdInlineItemList, f: &mut MarkdownFormatter) -> FormatResult<()> {
16	        if self.print_mode.is_normalize_words() {
17	            return self.fmt_normalize_words(node, f);
18	        } else if self.print_mode.is_all() {
19	            return self.fmt_trim_all(node, f);
20	        } else if self.print_mode.is_pristine() {
21	            return self.fmt_pristine(node, f);
22	        } else if self.print_mode.is_clean() {
23	            return self.fmt_clean(node, f);
24	        }
25	
26	        let mut joiner = f.join();
27	
28	        let mut seen_new_line = false;
29	        for (index, item) in node.iter().enumerate() {
30	            match item {
31	                AnyMdInline::MdTextual(text) => {
32	                    if text.is_empty_and_not_newline()? && seen_new_line {
33	                        let entry = format_with(|f| {
34	                            write!(
35	                                f,
36	                                [text.format().with_options(FormatMdTextualOptions {
37	                                    should_remove: true,
38	                                    trim_start: false,
39	                                    ..Default::default()
40	                                })]
41	                            )
42	                        });
43	                        joiner.entry(&entry);
44	                    } else if text.is_newline()? {
45	                        let entry = format_with(|f| {
46	                            write!(
47	                                f,
48	                                [
49	                                    text.format().with_options(FormatMdTextualOptions {
50	                                        should_remove: true,
51	                                        trim_start: false,
52	                                        ..Default::default()
53	                                    }),
54	                                    hard_line_break()
55	                                ]
56	                            )
57	                        });
58	                        seen_new_line = true;
59	                        joiner.entry(&entry);
60	                    } else {
61	                        joiner.entry(&text.format().with_options(FormatMdTextualOptions {
62	                            should_remove: false,
63	                            trim_start: self.print_mode.is_start() && index == 0,
64	                            ..Default::default()
65	                        }));
66	                    }
67	                }
68	
69	                AnyMdInline::MdHardLine(hard_line) => {
70	                    seen_new_line = true;
71	                    joiner.entry(&format_with(|f| {
