94	    /// Strips leading and trailing whitespace/hard-lines around the content.
95	    /// Items between the first and last non-empty nodes are kept as-is;
96	    /// items outside those boundaries are removed.
97	    fn fmt_trim_all(&self, node: &MdInlineItemList, f: &mut MarkdownFormatter) -> FormatResult<()> {
98	        let items: Vec<_> = node.iter().collect();
99	        let mut joiner = f.join();
100	
101	        let is_content = |item: &AnyMdInline| match item {
102	            AnyMdInline::MdTextual(text) => !text.is_empty().unwrap_or_default(),
103	            AnyMdInline::MdHardLine(_) => false,
104	            _ => true,
105	        };
106	
107	        // Find the first non-empty item from the left.
108	        let first_content = items.iter().position(&is_content);
109	
110	        // Find the first non-empty item from the right.
111	        let last_content = items
112	            .iter()
113	            .rev()
114	            .position(is_content)
115	            .map(|pos| items.len() - 1 - pos);
116	
117	        for (index, item) in items.iter().enumerate() {
118	            let is_before_content = first_content.is_none_or(|first| index < first);
119	            let is_after_content = last_content.is_none_or(|last| index > last);
120	
121	            if is_before_content || is_after_content {
122	                // Outside content boundaries: remove empty nodes.
123	                match item {
124	                    AnyMdInline::MdTextual(text) => {
125	                        joiner.entry(&text.format().with_options(FormatMdTextualOptions {
126	                            should_remove: true,
127	                            trim_start: true,
128	                            ..Default::default()
129	                        }));
130	                    }
