136	                        ));
137	                    }
138	                    _ => {
139	                        joiner.entry(&item.format());
140	                    }
141	                }
142	            } else {
143	                // Inside content boundaries: keep as-is.
144	                joiner.entry(&item.format());
145	            }
146	        }
147	
148	        joiner.finish()
149	    }
