hether `node` is the last hard line break in its paragraph block.\n///\n/// A hard line break is considered the last one when no content line follows it\n/// in the same block, i.e. it has no subsequent sibling or its next sibling is an\n/// empty text node (for example, a blank line separating two blocks). Interior\n/// hard line breaks — those followed by another content line — are not affected.\nfn is_last_hard_line(node: &MdHardLine) -> bool {\n    match node.syntax().next_sibling() {\n        None => true,\n        Some(next) => MdTextual::cast(next)\n            .and_then(|textual| textual.is_empty().ok())\n            .unwrap_or(false),\n    }\n}\n\npub(crate) struct FormatMdFormatHardLineOptions {\n    pub(crate) print_mode: TextPrintMode,\n}\n\nimpl FormatRuleWithOptions<MdHardLine> for FormatMdHardLine {\n    type Options = FormatMdFormatHardLineOptions;\n\n    fn with_options(mut self, options: Self::Options) -> Self {\n        self.print_mode = options.print_mode;\n        self\n    }\n}\n", "numLines": 78, "startLine": 1, "totalLines": 78}}
